window.__DATA_TODOS__ = {"stages": [{"slug": "sourcing", "name": "1 \u00b7 Sourcing & Ingestion", "blurb": "Getting raw data into the catalog in the first place \u2014 crawls, external datasets, registration.", "buckets": [{"slug": "dataset-ingestion", "stage": "sourcing", "name": "Dataset Ingestion & Registration", "blurb": "Getting a new or external dataset properly registered as a first-class, pinned Datakit source.", "count": 10, "tasks": [{"bucket": "dataset-ingestion", "source": "github", "ref": 6113, "title": "Assess new CC Science Crawl data as a source", "url": "https://github.com/marin-community/marin/issues/6113", "summary": "Assess the new Common Crawl Science Crawl as a candidate data source.", "howto": "Pull a sample, run it through the standard normalize/quality-score pipeline, and report volume, quality-score distribution, and any format surprises before deciding whether to register it as a full source.", "id": "dataset-ingestion-45"}, {"bucket": "dataset-ingestion", "source": "github", "ref": 6191, "title": "Maintain the agentic-trace dataset HF index", "url": "https://github.com/marin-community/marin/issues/6191", "summary": "Tracking issue to register HuggingFace links for agentic-trace teacher-model trajectory datasets produced by the OT-Agent datagen pipeline as they land.", "howto": "This is a living index, not a one-time fix \u2014 add the HF link for each new (source task-set, teacher model, context length) combination as its datagen sweep completes, and keep the naming convention consistent so the index stays scannable.", "id": "dataset-ingestion-46"}, {"bucket": "dataset-ingestion", "source": "github", "ref": 7127, "title": "Port FullyOpenMeditron corpus + evals as a medical SFT pilot", "url": "https://github.com/marin-community/marin/issues/7127", "summary": "Proposal to port the FullyOpenMeditron medical corpus and its evals onto Marin's post-training stack, as a medical-domain SFT pilot.", "howto": "Start with the evals, not the corpus: port FullyOpenMeditron's eval harness first so you have a way to measure the pilot, then register the corpus as a Datakit source and run a small SFT pilot against the ported evals before committing to a full-scale run.", "id": "dataset-ingestion-47"}, {"bucket": "dataset-ingestion", "source": "github", "ref": 7128, "title": "Build a medical midtraining corpus (GAP-Replay analog)", "url": "https://github.com/marin-community/marin/issues/7128", "summary": "Proposal for a medical mid-training corpus built as a GAP-Replay analog from sources already in Marin's catalog, companion to the Meditron SFT pilot.", "howto": "Inventory which in-catalog sources actually have medical content worth replaying, replicate the GAP-Replay construction method on that subset, and coordinate timing with #7127 since the two pilots share a domain and likely a shared eval set.", "id": "dataset-ingestion-48"}, {"bucket": "dataset-ingestion", "source": "github", "ref": 7193, "title": "Rehydrate Nemotron Legal placeholder subsets", "url": "https://github.com/marin-community/marin/issues/7193", "summary": "NVIDIA's Nemotron Legal datasets ship with unresolved `<CLAUSE>`/`<DOCUMENT>` placeholders; needs a rehydration step before they're usable training data.", "howto": "Identify the auxiliary source files the dataset card points to for resolving each placeholder type, write a rehydration step that joins them back in, and spot-check a sample of rehydrated documents against the original legal source before registering the result as trainable.", "id": "dataset-ingestion-49"}, {"bucket": "dataset-ingestion", "source": "github", "ref": 7813, "title": "Backtranslate instructions for scientific-software repos in Stack v3", "url": "https://github.com/marin-community/marin/issues/7813", "summary": "Generate instruction-backtranslation data for scientific-software repositories in Stack v3, where an LLM writes the brief a scientist would hand someone to build the given repo from scratch.", "howto": "Filter Stack v3 to scientific-software repos using existing domain classifiers, prompt an LLM to write the 'build brief' per repo with a few hand-checked examples as a calibration set, and spot-check a sample of generated briefs for plausibility before registering the output as a training source.", "id": "dataset-ingestion-50"}, {"bucket": "dataset-ingestion", "source": "github", "ref": 7826, "title": "Register 16 Nemotron v3 SFT datasets", "url": "https://github.com/marin-community/marin/issues/7826", "summary": "Register 16 Nemotron post-training v3 SFT datasets that exist on HuggingFace but aren't yet wired into Marin's dataset catalog.", "howto": "Write the registration as a small loop over the 16 known dataset IDs rather than 16 one-off entries, pinning each to a specific HF revision, and confirm each one loads and normalizes cleanly before marking the batch done.", "id": "dataset-ingestion-51"}, {"bucket": "dataset-ingestion", "source": "github", "ref": 8670, "title": "Add the Swallow Code dataset", "url": "https://github.com/marin-community/marin/issues/8670", "summary": "Add the publicly released Swallow Code dataset to Marin's data catalog.", "howto": "Register it following the standard external-dataset pattern (pin HF revision, run through normalize + quality scoring), and check for overlap with existing code sources before adding it to any production mix, since duplicate code sources are a known dedup pain point (#6854).", "id": "dataset-ingestion-52"}, {"bucket": "dataset-ingestion", "source": "github", "ref": 8671, "title": "Add the Code Alchemy dataset", "url": "https://github.com/marin-community/marin/issues/8671", "summary": "Add the Code Alchemy dataset to Marin's data catalog; requires merging with Stack v2 and a DeepMind dataset.", "howto": "Work out the merge key against Stack v2 and the DeepMind dataset first (likely a repo/file identity), since a bad merge key will silently create duplicates once dedup runs over the merged result \u2014 validate the merge on a small sample before running it at full scale.", "id": "dataset-ingestion-53"}, {"bucket": "dataset-ingestion", "source": "github", "ref": 8687, "title": "Register five Code Alchemy training subsets independently", "url": "https://github.com/marin-community/marin/issues/8687", "summary": "Register five specific Code Alchemy training subsets as independent, pinned Datakit sources.", "howto": "Depends on #8671 landing first. Once the merged Code Alchemy dataset exists, split it into the five named subsets as separate pinned sources so each can be included or excluded from a mix independently, rather than as one monolithic blob.", "id": "dataset-ingestion-54"}]}, {"slug": "cc-pdf-pipeline", "stage": "sourcing", "name": "Common Crawl / PDF Pipeline", "blurb": "The focus-crawl effort to turn Common Crawl PDFs and DOCX records into usable training documents, end to end.", "count": 9, "tasks": [{"bucket": "cc-pdf-pipeline", "source": "github", "ref": 2351, "title": "Design a spec-driven Common Crawl curation approach", "url": "https://github.com/marin-community/marin/issues/2351", "summary": "Proposes a spec-driven, declarative approach to large-scale pretraining data curation from Common Crawl, replacing today's multi-stage, hand-engineered pipelines with something more systematic.", "howto": "Start by writing the declarative spec format for one existing hand-engineered CC pipeline stage (pick the simplest, e.g. language filtering) as a proof of concept, and only generalize the spec language once that one stage runs correctly through it end to end.", "id": "cc-pdf-pipeline-55"}, {"bucket": "cc-pdf-pipeline", "source": "github", "ref": 7616, "title": "Build a PDF-to-document pipeline for the focus crawl (epic)", "url": "https://github.com/marin-community/marin/issues/7616", "summary": "Epic: build an end-to-end pipeline turning Common Crawl PDFs (the 'focus crawl') into usable training documents, with child issues covering each pipeline stage.", "howto": "Track this as the parent \u2014 the real work happens in its child issues (#7617 input/shape, #7618 extraction, #7619 quality filter, #7620 dedup/decontam, #7621 validation). Work them roughly in that order since each stage's output feeds the next.", "id": "cc-pdf-pipeline-56"}, {"bucket": "cc-pdf-pipeline", "source": "github", "ref": 7617, "title": "Pin the focus-crawl PDF input set and output shape", "url": "https://github.com/marin-community/marin/issues/7617", "summary": "Pin exactly which PDFs the focus-crawl pipeline reads and agree on a fixed output document shape, so downstream extraction/quality/dedup steps have a stable target.", "howto": "Do this before any downstream stage work \u2014 write down the exact WARC selection criteria and the target document schema (fields, required metadata) as a short spec doc, and get it reviewed, since every other stage in this epic depends on it not changing later.", "id": "cc-pdf-pipeline-57"}, {"bucket": "cc-pdf-pipeline", "source": "github", "ref": 7618, "title": "Build the PDF text-extraction step", "url": "https://github.com/marin-community/marin/issues/7618", "summary": "Build the core PDF-to-text extraction step, handling both born-digital PDFs (text already embedded) and scanned PDFs (needing OCR).", "howto": "Split into two code paths from the start: a fast text-layer extractor for born-digital PDFs, and an OCR fallback for scanned ones, with a cheap upfront classifier deciding which path a given PDF takes \u2014 trying to handle both with one extractor tends to do neither well.", "id": "cc-pdf-pipeline-58"}, {"bucket": "cc-pdf-pipeline", "source": "github", "ref": 7619, "title": "Build the PDF quality filter step", "url": "https://github.com/marin-community/marin/issues/7619", "summary": "Score the extracted PDF documents for quality and drop low-quality ones, following the approach used by the FinePDFs dataset.", "howto": "Reuse Marin's existing quality classifier rather than building a new one \u2014 apply it to extracted PDF text and compare score distributions against FinePDFs' published approach, then pick a cutoff calibrated the same way #7124 handles bucketization for other sources.", "id": "cc-pdf-pipeline-59"}, {"bucket": "cc-pdf-pipeline", "source": "github", "ref": 7620, "title": "Deduplicate and decontaminate focus-crawl PDF documents", "url": "https://github.com/marin-community/marin/issues/7620", "summary": "Deduplicate the extracted PDF documents and remove overlap with eval sets, largely by applying Marin's existing dedup/decontam tooling at scale.", "howto": "Plug the extracted PDF corpus into the existing fuzzy-dedup and decontam pipeline as just another source rather than building new tooling, but watch for PDF-specific artifacts (repeated headers/footers/boilerplate) that could trigger the over-merge bug in #6851.", "id": "cc-pdf-pipeline-60"}, {"bucket": "cc-pdf-pipeline", "source": "github", "ref": 7621, "title": "Compare a trained PDF-pipeline model against FinePDFs", "url": "https://github.com/marin-community/marin/issues/7621", "summary": "Train a model on the resulting PDF pipeline output and compare it head-to-head against an equal-sized sample of the released FinePDFs dataset, to validate the pipeline produces useful data.", "howto": "This is the epic's acceptance test \u2014 hold the token count exactly equal between the two training runs, use the same eval suite for both, and treat any meaningful gap as a signal to revisit extraction (#7618) or quality filtering (#7619) rather than the training run itself.", "id": "cc-pdf-pipeline-61"}, {"bucket": "cc-pdf-pipeline", "source": "github", "ref": 7736, "title": "Build a Common Crawl DOCX-to-text pipeline", "url": "https://github.com/marin-community/marin/issues/7736", "summary": "Build a pipeline that turns DOCX records found in Common Crawl WARC files into Marin's normalized document format.", "howto": "Reuse an existing DOCX-parsing library rather than hand-rolling XML parsing, map its output directly onto the same normalized document schema the PDF pipeline targets (#7617) so downstream quality/dedup steps can treat both sources identically.", "id": "cc-pdf-pipeline-62"}, {"bucket": "cc-pdf-pipeline", "source": "github", "ref": 8023, "title": "Implement the focus-crawl PDF-to-document pipeline", "url": "https://github.com/marin-community/marin/issues/8023", "summary": "Implementation PR for the focus-crawl PDF pipeline: plan/fetch 3.17M PDF records by coalesced WARC ranges and route each through text-layer extraction or OCR.", "howto": "This is the integration point for #7617/#7618 \u2014 implement WARC-range coalescing to minimize redundant fetches across the 3.17M records, and route each fetched PDF through the classifier-then-extractor split from #7618 rather than re-deciding that logic here.", "id": "cc-pdf-pipeline-63"}]}], "count": 19}, {"slug": "cleaning", "name": "2 \u00b7 Cleaning & Quality", "blurb": "Turning raw ingested data into something trustworthy enough to train on: dedup, decontam, scoring.", "buckets": [{"slug": "dedup-decontam", "stage": "cleaning", "name": "Deduplication & Decontamination", "blurb": "Exact and fuzzy dedup correctness/speed, decontamination recall, and scaling the dedup pipeline to production data volumes.", "count": 14, "tasks": [{"bucket": "dedup-decontam", "source": "github", "ref": 6851, "title": "Fix fuzzy dedup over-merging templated synthetic data", "url": "https://github.com/marin-community/marin/issues/6851", "summary": "Bug: fuzzy (minhash) dedup over-merges documents that merely share a template/boilerplate, causing large, unwanted content loss on templated synthetic data.", "howto": "Pull a sample of over-merged clusters, confirm they share boilerplate rather than substance, and add a check that discounts shared-template n-grams (or raises the minhash similarity threshold specifically for detected template-heavy sources) before falling back to a global threshold change.", "id": "dedup-decontam-19"}, {"bucket": "dedup-decontam", "source": "github", "ref": 6852, "title": "Rebalance decontamination's precision/recall trade-off", "url": "https://github.com/marin-community/marin/issues/6852", "summary": "Decontamination is heavily precision-favoring and has very low recall (~0.01%) on embedded or short-line contamination \u2014 a deliberate trade-off that may need rebalancing.", "howto": "Build a small labeled set of known embedded/short-line contamination cases, measure current recall against it, then experiment with lowering the match-length threshold or adding a secondary short-span matcher \u2014 track precision on a held-out clean set the whole time so the trade-off is measured, not assumed.", "id": "dedup-decontam-20"}, {"bucket": "dedup-decontam", "source": "github", "ref": 6854, "title": "Stop fuzzy dedup from wiping out entire sources", "url": "https://github.com/marin-community/marin/issues/6854", "summary": "Bug: fuzzy dedup removes a median of ~76% of documents per source, with some sources wiped out entirely (100% removed), destroying whole-source signal.", "howto": "Add per-source removal-rate reporting to the dedup pipeline and set an alert threshold (e.g. >90% removed) that flags a source for manual review instead of silently proceeding. For the already-wiped sources, check whether the cause is a template/boilerplate issue like #6851 before assuming they're genuinely duplicate-heavy.", "id": "dedup-decontam-21"}, {"bucket": "dedup-decontam", "source": "github", "ref": 7999, "title": "Record the canonical occurrence in global exact-dedup attributes", "url": "https://github.com/marin-community/marin/issues/7999", "summary": "Exact-dedup currently discards the metadata for the surviving ('canonical') copy of each duplicate group and only records the discarded ones; needs to record the canonical occurrence too.", "howto": "Find where the dedup step drops the surviving record's metadata, extend the output schema to keep it alongside the existing discarded-copy records, and add a test asserting every duplicate group's output includes exactly one canonical entry.", "id": "dedup-decontam-22"}, {"bucket": "dedup-decontam", "source": "github", "ref": 8155, "title": "Audit fuzzy-verification quality and thresholds", "url": "https://github.com/marin-community/marin/issues/8155", "summary": "Audit whether fuzzy-verification's duplicate-candidate filtering is actually removing true duplicates and keeping true non-duplicates, and whether its thresholds are well-calibrated.", "howto": "Hand-label a stratified sample of candidate pairs across the current threshold's decision boundary, compute precision/recall against that ground truth, and report where the threshold should move \u2014 this is a measurement task before it's a tuning task.", "id": "dedup-decontam-23"}, {"bucket": "dedup-decontam", "source": "github", "ref": 8218, "title": "Fix Nemotron Code normalization emitting duplicate IDs", "url": "https://github.com/marin-community/marin/issues/8218", "summary": "Nemotron Code v1/v2 normalization skips dedup mode, so byte-identical documents keep the same ID and break downstream joins that assume IDs are unique.", "howto": "Turn on the same dedup-mode ID assignment used by other normalize steps for the Nemotron Code v1/v2 path, re-run normalization, and add a uniqueness assertion on output IDs so a regression here fails loudly instead of breaking a downstream join silently.", "id": "dedup-decontam-24"}, {"bucket": "dedup-decontam", "source": "github", "ref": 8237, "title": "Add a full fuzzy-validation entry point reusing cached artifacts", "url": "https://github.com/marin-community/marin/issues/8237", "summary": "Add a full fuzzy-validation entry point that reuses cached normalize/MinHash/fuzzy-candidate artifacts, and repack the prior Focus Crawl candidates into the current shard layout.", "howto": "Wire a new entry point that reads from the existing cached normalize/MinHash/candidate artifacts rather than recomputing them, write the Focus Crawl repack as a one-time migration step, and confirm the new entry point reproduces a known-good validation result before relying on it.", "id": "dedup-decontam-25"}, {"bucket": "dedup-decontam", "source": "github", "ref": 8301, "title": "Speed up fuzzy duplicate verification", "url": "https://github.com/marin-community/marin/issues/8301", "summary": "Speed up fuzzy duplicate verification by moving document lookups into worker-local subprocess stores and bounding shard-group sizes.", "howto": "Profile the current lookup path to confirm cross-process document fetches are the bottleneck, move the hot lookup into a worker-local subprocess store, and cap shard-group size so no single group dominates wall-clock \u2014 measure before/after on the same shard set.", "id": "dedup-decontam-26"}, {"bucket": "dedup-decontam", "source": "github", "ref": 8327, "title": "Make decontamination restartable at scale", "url": "https://github.com/marin-community/marin/issues/8327", "summary": "Scale decontamination to run as restartable Bloom-index, drop-set, mark, and report stages so large-scale runs can resume after failures.", "howto": "Split the monolithic decontam run into the four named stages as separate ExecutorSteps with persisted intermediate outputs, so a failure in 'mark' doesn't force rebuilding the Bloom index from scratch. Validate by killing a run mid-stage and confirming a resume picks up correctly.", "id": "dedup-decontam-27"}, {"bucket": "dedup-decontam", "source": "github", "ref": 8328, "title": "Register v4 decontamination outputs as pinned StepSpec paths", "url": "https://github.com/marin-community/marin/issues/8328", "summary": "Register v4 decontamination outputs for all 292 sources as resolvable, pinned paths in the production StepSpec graph, replacing a manual source map.", "howto": "Generate the StepSpec entries programmatically from the same source list the manual map currently uses (rather than retyping 292 entries by hand), diff the pinned paths against what's actually on disk, and cut the manual map over once every source resolves cleanly.", "id": "dedup-decontam-28"}, {"bucket": "dedup-decontam", "source": "github", "ref": 8723, "title": "Solve complete fuzzy-duplicate clusters at scale", "url": "https://github.com/marin-community/marin/issues/8723", "summary": "Resolve each fuzzy-duplicate candidate cluster fully using directional word n-gram containment, scanning small clusters exactly and bounding large-cluster work with a rare-n-gram index.", "howto": "Implement exact resolution for small clusters first (it's the easy 80%), then add the rare-n-gram index specifically to bound large-cluster blowup, and validate against a hand-checked sample of both small and large clusters before running at full scale.", "id": "dedup-decontam-29"}, {"bucket": "dedup-decontam", "source": "github", "ref": 8724, "title": "Materialize fuzzy-duplicate cluster text", "url": "https://github.com/marin-community/marin/issues/8724", "summary": "Materialize the actual text for fuzzy-duplicate clusters (joining candidate attributes to normalized text) and record a versioned completion manifest.", "howto": "Implement the join from candidate attributes to normalized text as a batch step, write a versioned manifest recording which clusters completed, and make the step idempotent so a partial run can resume from the manifest rather than restarting.", "id": "dedup-decontam-30"}, {"bucket": "dedup-decontam", "source": "github", "ref": 8725, "title": "Verify materialized fuzzy clusters", "url": "https://github.com/marin-community/marin/issues/8725", "summary": "Verify materialized fuzzy-duplicate clusters by solving grouped clusters in bounded distributed tasks and reconciling markers back to normalized shards.", "howto": "Depends on #8723 and #8724 landing first. Once they have, add a reconciliation pass that checks every marker in the normalized shards traces back to a solved, materialized cluster, and report any orphaned markers as a data-integrity bug rather than silently dropping them.", "id": "dedup-decontam-31"}, {"bucket": "dedup-decontam", "source": "github", "ref": 8806, "title": "Study deduplication's effect on scaling laws", "url": "https://github.com/marin-community/marin/issues/8806", "summary": "Proposal to systematically study how duplicated data affects model performance and scaling laws, building on prior published findings that duplication measurably hurts scaling.", "howto": "Design a small controlled ablation: hold total tokens fixed while varying injected duplication rate across a few small-scale training runs, and fit loss-vs-duplication curves comparable to the published results this proposal is building on before committing to a large-scale version.", "id": "dedup-decontam-32"}]}, {"slug": "quality-scoring-labeling", "stage": "cleaning", "name": "Data Quality Scoring & Labeling", "blurb": "The document-level quality classifier and domain-clustering signals used to bucket and filter training data.", "count": 5, "tasks": [{"bucket": "quality-scoring-labeling", "source": "github", "ref": 6850, "title": "Fix lexical domain embedding collapsing code into one cluster", "url": "https://github.com/marin-community/marin/issues/6850", "summary": "Bug: the lexical embedding used for domain clustering collapses nearly all code documents into a single cluster, making the domain axis useless for code.", "howto": "Swap the lexical embedding for a code-aware embedding (or add code-specific features like language/AST-shape) just for documents pre-classified as code, since a general-text lexical embedding is unlikely to ever separate code meaningfully by domain.", "id": "quality-scoring-labeling-76"}, {"bucket": "quality-scoring-labeling", "source": "github", "ref": 6855, "title": "Fix severely imbalanced domain clusters with catch-alls", "url": "https://github.com/marin-community/marin/issues/6855", "summary": "Bug: the k=40 domain clustering forms severely imbalanced catch-all clusters that lump unrelated content together, making the domain axis largely uninformative.", "howto": "Inspect the largest catch-all clusters to see what's actually being lumped together, then either raise k specifically in the dense region those clusters occupy or add a secondary split pass for any cluster above a size threshold, rather than raising k globally.", "id": "quality-scoring-labeling-77"}, {"bucket": "quality-scoring-labeling", "source": "github", "ref": 7124, "title": "Decide the quality bucketization scheme (absolute vs quantile)", "url": "https://github.com/marin-community/marin/issues/7124", "summary": "Open design decision: whether the quality scorer's [0,1] score should be bucketed at fixed absolute cutpoints or by quantile, and how to anchor that calibration.", "howto": "Plot the score distribution across a few representative sources side by side \u2014 if the distribution shape varies a lot by source, quantile bucketing will behave more consistently; if it's stable, absolute cutpoints are simpler and more interpretable. Make the call from that plot, not in the abstract.", "id": "quality-scoring-labeling-78"}, {"bucket": "quality-scoring-labeling", "source": "github", "ref": 8121, "title": "Fix quality classifier ranking math and code near chance", "url": "https://github.com/marin-community/marin/issues/8121", "summary": "The deployed quality classifier still ranks math and code documents near chance (far worse than its overall Spearman correlation), despite an earlier fix attempt.", "howto": "Check whether the training data for the classifier under-represents math/code relative to its share of the real corpus \u2014 a near-chance ranking on a specific domain usually means the classifier never saw enough labeled examples there, not a modeling bug. Rebalance the training sample toward math/code before retraining.", "id": "quality-scoring-labeling-79"}, {"bucket": "quality-scoring-labeling", "source": "github", "ref": 8453, "title": "Move from a single quality score to multi-axis data labeling", "url": "https://github.com/marin-community/marin/issues/8453", "summary": "Move from a single scalar quality score to multi-axis data labeling, drawing on published data-selection methods (MATES, RegMix, Meta-rater) to better capture what makes a document valuable.", "howto": "This depends on the MATES/Group-MATES evaluation in #6521 \u2014 don't duplicate that work. Once a preferred method is chosen there, define the specific axes (e.g. factuality, difficulty, domain-fit) and pilot multi-axis labeling on one source before rearchitecting the pipeline's schema everywhere.", "id": "quality-scoring-labeling-80"}]}], "count": 19}, {"slug": "mixing", "name": "3 \u00b7 Mixing for Pretraining", "blurb": "Deciding what actually goes into a pretraining run, and how much of each thing.", "buckets": [{"slug": "data-mix-strategy", "stage": "mixing", "name": "Data Mix & Curation Strategy", "blurb": "What goes into the pretraining mix and why: mixture search, data-selection methods, and the diagnostics that justify a mix decision.", "count": 12, "tasks": [{"bucket": "data-mix-strategy", "source": "github", "ref": 2393, "title": "Build Domain-Phase Data Mixture Swarm experiment support", "url": "https://github.com/marin-community/marin/issues/2393", "summary": "Initial code to support RegMix-style data-mixture experiments that have discrete phases and epoching, rather than a single static mixture.", "howto": "Extend the existing swarm experiment harness to accept a list of (mixture, phase-length) pairs instead of one static mixture, run a small validation swarm with two phases to confirm phase transitions apply correctly, then hand it to the mixture-strategy owners to use for real experiments.", "id": "data-mix-strategy-33"}, {"bucket": "data-mix-strategy", "source": "github", "ref": 5197, "title": "Evaluate metadata conditioning (MeCo) for pretraining efficiency", "url": "https://github.com/marin-community/marin/issues/5197", "summary": "Evaluate 'metadata conditioning' (MeCo), a published technique for improving pretraining data efficiency, as a candidate addition to Marin's data pipeline.", "howto": "Re-implement MeCo's conditioning scheme at small scale exactly as published, run a paired ablation (with/without) on a fixed token budget, and report whether the published gains reproduce in Marin's stack before proposing it for production mixes.", "id": "data-mix-strategy-34"}, {"bucket": "data-mix-strategy", "source": "github", "ref": 6037, "title": "Finalize August hero run data prep", "url": "https://github.com/marin-community/marin/issues/6037", "summary": "Definition-of-done tracking issue for the August hero run's data prep: decide new dataset inclusions, add a Common Crawl proof-of-concept crawl, add more code data, and evaluate the new mix.", "howto": "Work the checklist in order \u2014 lock dataset inclusions first since everything else depends on them, then land the CC proof-of-concept crawl and additional code data as separate registered sources, and close this out with a mix evaluation run rather than marking it done on inclusion alone.", "id": "data-mix-strategy-35"}, {"bucket": "data-mix-strategy", "source": "github", "ref": 6521, "title": "Evaluate MATES/Group-MATES data selection", "url": "https://github.com/marin-community/marin/issues/6521", "summary": "Evaluate published data-selection methods MATES and Group-MATES as candidates for Marin's own data-selection pipeline.", "howto": "Implement each method's scoring function against a fixed small-scale corpus, compare the resulting selected subsets and downstream eval scores against Marin's current selection baseline, and report which (if either) is worth porting to production scale.", "id": "data-mix-strategy-36"}, {"bucket": "data-mix-strategy", "source": "github", "ref": 6610, "title": "Run a production-scale mixture swarm", "url": "https://github.com/marin-community/marin/issues/6610", "summary": "Run a production-scale mixture swarm to optimize and validate a data mixture, rather than a smaller-scale exploratory one.", "howto": "Confirm the swarm harness and compute budget are ready for production scale before launching (check #2393 and #8633 for prerequisite tooling), then run the swarm, and validate the winning mixture with a held-out eval suite rather than just its swarm objective score.", "id": "data-mix-strategy-37"}, {"bucket": "data-mix-strategy", "source": "github", "ref": 6712, "title": "Strengthen data-selection diagnostics", "url": "https://github.com/marin-community/marin/issues/6712", "summary": "Strengthen the evals/perplexity/diagnostic signals that predict downstream model quality, to make better data-selection decisions with less trial and error.", "howto": "Inventory which existing diagnostics (perplexity, small-scale eval proxies) actually correlated with final model quality in past runs, drop or fix the ones that didn't, and propose one or two new candidate signals grounded in that retrospective rather than guessing fresh.", "id": "data-mix-strategy-38"}, {"bucket": "data-mix-strategy", "source": "github", "ref": 6713, "title": "Curate and tune the pretraining data mix; productionize CoreWeave pipeline", "url": "https://github.com/marin-community/marin/issues/6713", "summary": "Ongoing charter to curate and tune the pretraining data mix and productionize the CoreWeave data pipeline.", "howto": "This is a standing charter rather than a single fix \u2014 treat it as an umbrella and file/link concrete sub-issues (a specific mix change, a specific CoreWeave pipeline gap) under it rather than trying to close it directly.", "id": "data-mix-strategy-39"}, {"bucket": "data-mix-strategy", "source": "github", "ref": 6750, "title": "Evaluate web-graph centrality as a document feature", "url": "https://github.com/marin-community/marin/issues/6750", "summary": "Evaluate whether web-graph centrality (PageRank/betweenness/Katz) computed over Common Crawl's link graph is a useful document feature for the next data mix.", "howto": "Compute at least PageRank over a sampled slice of the CC link graph, join it onto existing documents as a feature, and check its correlation with known-good/known-bad quality labels before investing in the more expensive betweenness/Katz variants.", "id": "data-mix-strategy-40"}, {"bucket": "data-mix-strategy", "source": "github", "ref": 6757, "title": "Iso-FLOP compare curated vs proportional datakit mix (MoE)", "url": "https://github.com/marin-community/marin/issues/6757", "summary": "Decide, via an iso-FLOP side-by-side experiment, whether a curated datakit mix beats a proportional one for MoE models \u2014 an open methodology question feeding future mix decisions.", "howto": "Hold total FLOPs fixed, train matched curated-vs-proportional runs across the stated d512\u2013d1280 range, and report loss/eval deltas per size point \u2014 the point of this issue is the comparison methodology, so keep every other hyperparameter identical between arms.", "id": "data-mix-strategy-41"}, {"bucket": "data-mix-strategy", "source": "github", "ref": 7067, "title": "Stop mixture-sweep evidence from being stranded by bucket changes", "url": "https://github.com/marin-community/marin/issues/7067", "summary": "Data-mixture optimization results are indexed by opaque bucket numbers with no record of what a bucket actually contains, so renaming or changing buckets strands prior optimization evidence.", "howto": "Add a content fingerprint (e.g. a hash of the bucket's source list and weights) alongside the numeric bucket ID in every recorded result, so future lookups can match on content even after a renumbering, and backfill fingerprints for existing recorded evidence where the original bucket definitions are still recoverable.", "id": "data-mix-strategy-42"}, {"bucket": "data-mix-strategy", "source": "github", "ref": 7162, "title": "Set up a recurring per-crawl data ablation feedback loop", "url": "https://github.com/marin-community/marin/issues/7162", "summary": "Proposal for a recurring, standing feedback loop that runs a small data ablation on each new Common Crawl snapshot as it's added.", "howto": "Define the smallest ablation that's informative (e.g. a fixed small-scale training run comparing with/without the new snapshot), automate its trigger off new-crawl registration, and pipe results into the existing eval-tracking dashboard so the loop doesn't need a human to remember to check it.", "id": "data-mix-strategy-43"}, {"bucket": "data-mix-strategy", "source": "github", "ref": 8633, "title": "Add transfer optimization across data-mixture swarm experiments", "url": "https://github.com/marin-community/marin/issues/8633", "summary": "Fit a shared-content transfer model (Gaussian process) across historical data-mixture swarm experiments to pick good two-phase mixtures for a new target run with fewer live experiments.", "howto": "Gather historical swarm results into a common feature representation (shared content across mixtures), fit a GP on that history, and validate by holding out one past swarm and checking whether the GP would have picked a mixture close to what the full swarm found.", "id": "data-mix-strategy-44"}]}], "count": 12}, {"slug": "post-training", "name": "4 \u00b7 Post-Training & RL Data", "blurb": "Task and agentic data used after pretraining \u2014 TaskTrove, RL data pools, post-training schemas.", "buckets": [{"slug": "tasktrove-quality", "stage": "post-training", "name": "TaskTrove Data Quality & Auditing", "blurb": "TaskTrove is Marin's ~1.7M-task agentic/RL dataset (93 sources, converted from open-thoughts/TaskTrove). This bucket is about finding and fixing tasks that are broken, duplicated, or gameable.", "count": 8, "tasks": [{"bucket": "tasktrove-quality", "source": "github", "ref": 8937, "title": "Fix TaskTrove r2egym pandas/numpy tasks that reward a no-op patch", "url": "https://github.com/marin-community/marin/issues/8937", "summary": "Found that most pandas/numpy tasks in a TaskTrove slice (r2egym) reward a no-op patch \u2014 the tests pass without any real fix \u2014 plus several smaller correctness findings.", "howto": "Root cause is almost certainly the verifier importing the pre-installed library instead of the agent's actual checkout \u2014 check the test harness's import path first. Fix that, then re-run every affected task's tests against both a no-op patch (should fail) and the real gold patch (should pass) as a regression check.", "id": "tasktrove-quality-64"}, {"bucket": "tasktrove-quality", "source": "github", "ref": 9058, "title": "Deduplicate exact instruction copies in TaskTrove", "url": "https://github.com/marin-community/marin/issues/9058", "summary": "Deduplicate exact instruction copies within each published TaskTrove source before export \u2014 the default split currently has 1.7M+ task archives across 93 sources with unknown duplication.", "howto": "Hash each task's instruction.md bytes, group exact matches within a source, and keep the shortest surviving path per group as the canonical copy. Note the related Discord thread \u2014 an earlier attempt hit HuggingFace API rate limits mid-run, so batch/throttle your export calls or request a higher account limit before starting.", "id": "tasktrove-quality-65"}, {"bucket": "tasktrove-quality", "source": "github", "ref": 9083, "title": "Validate TaskTrove repository and judge tasks in their runtime", "url": "https://github.com/marin-community/marin/issues/9083", "summary": "Validate that TaskTrove's repository and judge tasks actually run correctly in their intended runtime, following a clean release that recovered thousands of previously-rejected tasks.", "howto": "Write a harness that actually executes each repository/judge task in its declared runtime (not just schema-validates it), and treat any task that errors, hangs, or times out as a candidate for rejection or repair rather than assuming recovery alone means correctness.", "id": "tasktrove-quality-66"}, {"bucket": "tasktrove-quality", "source": "discord", "ref": "data-curation \u00b7 2026-09-05", "title": "Fix the QASPER reading-comprehension task in TaskTrove", "url": null, "summary": "An audit found roughly half of the QASPER-derived tasks are missing the source paper entirely, so the agent is graded on answering a question about a document it was never given.", "howto": "Trace the QASPER ingestion step to find where the source-paper attachment gets dropped \u2014 likely a join key mismatch between the question set and the paper corpus \u2014 and re-attach papers for the affected tasks rather than deleting them, since the questions themselves are probably still valid.", "id": "tasktrove-quality-67"}, {"bucket": "tasktrove-quality", "source": "discord", "ref": "data-curation \u00b7 2026-09-05", "title": "Purge or repair broken tasks in TaskTrove's r2egym slice", "url": null, "summary": "A sample audit found a meaningful share of r2egym tasks missing problem-statement text, plus a further batch whose reference solution fails its own test suite.", "howto": "Split this into two passes: tasks missing problem-statement text should be purged (they're not repairable without the original source), while tasks with a failing reference solution need the gold patch re-verified against a clean environment before deciding whether to fix the patch or drop the task.", "id": "tasktrove-quality-68"}, {"bucket": "tasktrove-quality", "source": "discord", "ref": "data-curation \u00b7 2026-09-04", "title": "Prototype a model-based auditor for TaskTrove quality", "url": null, "summary": "A contributor is exploring using a small/medium model to automatically audit every TaskTrove task after a manual spot-check turned up a high rate of broken or low-value tasks.", "howto": "Calibrate the auditor model against the manual spot-check results first \u2014 feed it the same tasks a human already scored and tune its prompt/threshold to match human judgment \u2014 before trusting it to flag tasks a human hasn't looked at.", "id": "tasktrove-quality-69"}, {"bucket": "tasktrove-quality", "source": "discord", "ref": "data-curation \u00b7 2026-09-09", "title": "Standardize TaskTrove synthetic task generation on script-based templates", "url": null, "summary": "Guidance from a maintainer: avoid non-reproducible, LLM-directly-intermediated synthetic task generation going forward; have agents write a task template and embed it in a script instead.", "howto": "Audit existing synthetic-task-generation code for any step that has an LLM directly emit the final task rather than a reusable template, and refactor those to have the agent write a parameterized script/template instead \u2014 the goal is that re-running the script reproduces the same task deterministically.", "id": "tasktrove-quality-70"}, {"bucket": "tasktrove-quality", "source": "discord", "ref": "data-curation \u00b7 2026-09-10", "title": "Get TaskTrove's HuggingFace account rate limits raised to unblock dedup", "url": null, "summary": "An attempted exact-duplicate removal pass over TaskTrove's many duplicate tasks was abandoned mid-way because HF API rate limits made it impractical; a teammate suggested requesting a higher limit through a shared account channel.", "howto": "This is an access/ops task, not an engineering one \u2014 file the account-limit request through whatever channel Marin uses for HF org administration, and in parallel add batching/backoff to the dedup export script (see #9058) so it's resilient to rate limits even after the increase lands.", "id": "tasktrove-quality-71"}]}, {"slug": "tasktrove-coverage", "stage": "post-training", "name": "TaskTrove Coverage & New Sources", "blurb": "Growing TaskTrove into domains and competencies it doesn't cover yet, and deciding what to add next.", "count": 4, "tasks": [{"bucket": "tasktrove-coverage", "source": "github", "ref": 7418, "title": "Fill TaskTrove verifier gaps for 43 of 95 SFT task sources", "url": "https://github.com/marin-community/marin/issues/7418", "summary": "Of 95 SFT task-generation strategies surveyed from the OpenThoughts-Agent paper, 43 have no usable TaskTrove verifier yet \u2014 a gap-filling task list for verifier coverage.", "howto": "Triage the 43 by how mechanical their verification is (unit-test-style tasks are usually quick to wire up; open-ended generation tasks need a real rubric or judge model) and knock out the mechanical ones first to shrink the list fast, saving judgment-heavy verifiers for a dedicated pass.", "id": "tasktrove-coverage-72"}, {"bucket": "tasktrove-coverage", "source": "discord", "ref": "data-curation \u00b7 2026-09-04", "title": "Prioritize which under-covered TaskTrove competency domains to fill next", "url": null, "summary": "Following a full coverage map of TaskTrove against a technical-competency taxonomy, the team is weighing which uncovered domains to prioritize, including ones tied to other active research branches.", "howto": "Cross-reference the coverage map against which domains matter most for near-term eval targets or active research branches (RL, long-context, agentic work) and prioritize those over generically 'more coverage' \u2014 coverage gaps that nothing downstream currently exercises are lower priority.", "id": "tasktrove-coverage-73"}, {"bucket": "tasktrove-coverage", "source": "discord", "ref": "openthoughts-next \u00b7 2026-09-10", "title": "Integrate new agent-skill and reasoning data sources into TaskTrove", "url": null, "summary": "A data working session settled on four primary new source types to bring into TaskTrove, starting with agent-skill-file corpora, to widen task coverage.", "howto": "Start with agent-skill-file corpora as agreed, since it's the concrete first pick \u2014 write a converter that turns a skill file into TaskTrove's task-archive format (instruction + verifier contract) and validate a small batch by hand before scaling up to the other three source types.", "id": "tasktrove-coverage-74"}, {"bucket": "tasktrove-coverage", "source": "discord", "ref": "data-curation \u00b7 2026-09-09", "title": "Evaluate adding Kaggle-style verifiable tasks to TaskTrove", "url": null, "summary": "A contributor proposed pulling in existing modeling/data-analysis problems from a public ML-competition archive, since they score automatically against held-out labels and TaskTrove is thin in this area.", "howto": "Pick a handful of competitions with clean, held-out-label scoring (avoid ones needing a live leaderboard submission), convert their problem statement + scoring script into TaskTrove's verifier-contract format, and check license terms for redistribution before ingesting at scale.", "id": "tasktrove-coverage-75"}]}, {"slug": "rl-post-training", "stage": "post-training", "name": "RL & Post-Training Data", "blurb": "Data pools, schemas, and curation specific to RL and post-training runs, as distinct from pretraining data.", "count": 5, "tasks": [{"bucket": "rl-post-training", "source": "github", "ref": 6496, "title": "Scope the Post-training Data manager function", "url": "https://github.com/marin-community/marin/issues/6496", "summary": "Epic defining the scope, ownership, and near-term work of the 'Post-training Data' function within Marin, including its compute envelope and boundary with other roles.", "howto": "Treat this as an org-design epic, not an engineering task \u2014 the concrete engineering work lives in its linked children like #7799 and #9125. Its own progress is measured by getting scope/ownership/compute-envelope written down and agreed, not by code.", "id": "rl-post-training-81"}, {"bucket": "rl-post-training", "source": "github", "ref": 6707, "title": "Curate RL training data and run ablations", "url": "https://github.com/marin-community/marin/issues/6707", "summary": "Ongoing charter to curate RL training data and run experiments/ablations on what actually drives post-training gains, coordinating across the post-training milestone.", "howto": "As a standing charter, make progress visible by filing specific ablation proposals as their own linked issues (e.g. a specific data-mix-for-RL question) rather than trying to resolve this issue itself.", "id": "rl-post-training-82"}, {"bucket": "rl-post-training", "source": "github", "ref": 7799, "title": "Build a normalized, versioned post-training data pool", "url": "https://github.com/marin-community/marin/issues/7799", "summary": "Post-training datasets still carry source-specific prompt/response/metadata schemas; build a normalized, versioned post-training data pool with a consistent schema across sources.", "howto": "Design the normalized schema against the 2-3 most different existing source formats first (to make sure it actually generalizes), write converters into that schema per source, and version the pool itself so a downstream consumer can pin to a specific pool version rather than 'whatever's current'.", "id": "rl-post-training-83"}, {"bucket": "rl-post-training", "source": "github", "ref": 9125, "title": "Let SkyRL read TaskTrove Clean directly", "url": "https://github.com/marin-community/marin/issues/9125", "summary": "Let SkyRL post-training experiments select TaskTrove Clean rows directly by source, tags, mode, limit, and seed, rather than going through an intermediate export.", "howto": "Add a query interface in front of TaskTrove Clean supporting filter-by-source/tags/mode plus limit and seed for reproducible sampling, and point SkyRL's experiment config at that interface directly \u2014 the goal is deleting the intermediate export step entirely, not just adding a faster export.", "id": "rl-post-training-84"}, {"bucket": "rl-post-training", "source": "discord", "ref": "reinforcement-learning \u00b7 2026-09-04", "title": "Build a submission-format-robustness RL dataset from R2E-Gym tasks", "url": null, "summary": "Proposal to have an agent generate many differently-formatted copies of the same task so models can be hardened against reward-hacking on submission format rather than task substance.", "howto": "Pick a small set of R2E-Gym tasks, generate format variants programmatically (whitespace, ordering, wrapper text) rather than by hand so the variant set is large and cheap, and verify the underlying verifier still scores all variants of a correct solution identically before using this for training.", "id": "rl-post-training-85"}]}], "count": 17}, {"slug": "evaluation", "name": "5 \u00b7 Evaluation Data", "blurb": "Data used to measure a model, not train it \u2014 building and maintaining the eval sets themselves.", "buckets": [{"slug": "eval-dataset-construction", "stage": "evaluation", "name": "Eval Dataset Construction & Quality", "blurb": "Building and maintaining the datasets evals are scored against, as opposed to running the evals themselves.", "count": 2, "tasks": [{"bucket": "eval-dataset-construction", "source": "github", "ref": 7229, "title": "Correct Delphi HumanEval shot-count metadata", "url": "https://github.com/marin-community/marin/issues/7229", "summary": "Fix incorrect shot-count metadata recorded for the Delphi HumanEval evaluation.", "howto": "Find where the shot count is actually determined at eval-run time versus what gets recorded in metadata, fix the mismatch, and re-run one known evaluation to confirm the corrected metadata now matches the true prompt construction.", "id": "eval-dataset-construction-86"}, {"bucket": "eval-dataset-construction", "source": "github", "ref": 9073, "title": "Assess AI-generated content's effect on the uncheatable eval dataset", "url": "https://github.com/marin-community/marin/issues/9073", "summary": "Open question: how does the rising share of AI-generated content inside the 'uncheatable' evaluation dataset affect the validity of its performance results?", "howto": "Start by measuring the actual share of AI-generated content in the current dataset (a detector or provenance check, not a guess), then compare model rankings on the AI-generated-heavy subset versus the rest \u2014 if rankings diverge meaningfully, that's the evidence needed to justify a dataset refresh.", "id": "eval-dataset-construction-87"}]}], "count": 2}, {"slug": "cross-cutting", "name": "Cross-Cutting: Infra & Documentation", "blurb": "Underlies every stage above rather than belonging to one: pipeline tooling/reliability and provenance docs.", "buckets": [{"slug": "datakit-reliability", "stage": "cross-cutting", "name": "Datakit Pipeline Reliability & Tooling", "blurb": "Bugs and missing guardrails in the datakit pipeline machinery itself: sharding, caching, worker sizing, reproducibility pins, and CI canaries.", "count": 19, "tasks": [{"bucket": "datakit-reliability", "source": "github", "ref": 807, "title": "Verify a dataset download pulled the whole dataset", "url": "https://github.com/marin-community/marin/issues/807", "summary": "Dataset downloads don't verify they actually pulled the complete dataset, risking silent truncation.", "howto": "Add a post-download check that compares file/row counts (or a manifest checksum, if the source publishes one) against what the source declares, and fail the download step loudly rather than letting a truncated shard flow downstream. Start with the highest-volume download modules and backfill the rest.", "id": "datakit-reliability-0"}, {"bucket": "datakit-reliability", "source": "github", "ref": 6858, "title": "Fix massively over-sharded clustered store", "url": "https://github.com/marin-community/marin/issues/6858", "summary": "Bug: the clustered data store is massively over-sharded (~1 element per shard in places), forcing reads to open hundreds of nearly-empty files.", "howto": "Instrument the clustering step to log shard-size distribution, find where the sharding key degenerates to near-unique values, and add a minimum-shard-size merge pass before write. Validate on the worst-offending cluster first since it's the cheapest reproduction.", "id": "datakit-reliability-1"}, {"bucket": "datakit-reliability", "source": "github", "ref": 6896, "title": "Thread tokenizer revision through load_tokenizer for a true byte-pin", "url": "https://github.com/marin-community/marin/issues/6896", "summary": "The tokenizer-revision hash is now threaded through the tokenize step but the underlying loader ignores it, breaking the intended byte-for-byte reproducibility pin.", "howto": "Trace load_tokenizer's call sites, pass the revision hash through to the underlying HF/tokenizers loader call, and add a test that pins two different revisions of the same tokenizer and asserts different byte output. This is a narrow plumbing fix, not a design change.", "id": "datakit-reliability-2"}, {"bucket": "datakit-reliability", "source": "github", "ref": 6897, "title": "Version-tag the decontam bloom eval corpus instead of re-keying per region", "url": "https://github.com/marin-community/marin/issues/6897", "summary": "The decontamination bloom filter's eval corpus is keyed by a region-specific path, so it needlessly re-keys per region instead of carrying a stable version tag.", "howto": "Replace the path-derived cache key with an explicit version string set at corpus-build time, and cache/lookup by that tag regardless of region. Confirm the fix by building the bloom index in two regions and checking they now hit the same cache entry.", "id": "datakit-reliability-3"}, {"bucket": "datakit-reliability", "source": "github", "ref": 6898, "title": "Pin/checksum download modules for reproducible normalize inputs", "url": "https://github.com/marin-community/marin/issues/6898", "summary": "Most datakit download modules don't pin a HuggingFace revision or checksum, so normalize-step inputs aren't reproducible across runs.", "howto": "Audit download modules for a missing `revision=` argument or checksum manifest, add both, and fail fast if a re-download doesn't match the pinned checksum. Do the highest-traffic sources first; this is mechanical but touches many files.", "id": "datakit-reliability-4"}, {"bucket": "datakit-reliability", "source": "github", "ref": 6997, "title": "Persist/cache a distributed dataset across driver-loop iterations", "url": "https://github.com/marin-community/marin/issues/6997", "summary": "A distributed dataset gets re-read from scratch on every iteration of a driver loop instead of being persisted/cached, wasting repeated large-table reads.", "howto": "Wrap the dataset handle in a cached/persisted form (e.g. an in-memory or disk-backed cache keyed by the query) at the top of the driver loop instead of inside it, and confirm with a wall-clock before/after on one full loop. Watch memory headroom if caching in-process.", "id": "datakit-reliability-5"}, {"bucket": "datakit-reliability", "source": "github", "ref": 7187, "title": "Test the fast-transformer quality scorer's TPU performance", "url": "https://github.com/marin-community/marin/issues/7187", "summary": "Test whether the fast-transformer quality scorer \u2014 too slow on CPU for practical use \u2014 runs fast enough on TPU to become the production scorer.", "howto": "Port the scorer's inference path to run on a small TPU slice, benchmark throughput against the CPU baseline and against the volume the production pipeline needs to sustain, and report a go/no-go with the numbers rather than a qualitative impression.", "id": "datakit-reliability-6"}, {"bucket": "datakit-reliability", "source": "github", "ref": 7244, "title": "Emit a chat-format TokenizedCache so SFT steps come from epochs", "url": "https://github.com/marin-community/marin/issues/7244", "summary": "SFT launcher hand-computes training steps from token/sequence-length math; needs a proper chat-format tokenized cache so step counts can instead come from a requested number of epochs.", "howto": "Extend the existing TokenizedCache abstraction to a chat-format variant that records example count, then compute num_train_steps as epochs \u00d7 examples / batch_size at launch time instead of the current manual arithmetic. Keep the old path working behind a flag until parity is confirmed.", "id": "datakit-reliability-7"}, {"bucket": "datakit-reliability", "source": "github", "ref": 7273, "title": "Build a canonical raw-sample -> datakit -> pretrain -> eval reference pipeline", "url": "https://github.com/marin-community/marin/issues/7273", "summary": "There is no single canonical reference pipeline exercising raw-sample-to-eval end-to-end; datakit, pretraining, and eval stages are only tested separately today.", "howto": "Pick the smallest realistic dataset that exercises every stage, wire it as one ExecutorStep graph from raw sample through a tiny pretrain run to an eval score, and check it into CI as a slow-but-required integration test. Treat any stage that can't plug in cleanly as its own follow-up bug.", "id": "datakit-reliability-8"}, {"bucket": "datakit-reliability", "source": "github", "ref": 7434, "title": "Replace shuffle-store bucket_token_hint with a self-contained counting pre-pass", "url": "https://github.com/marin-community/marin/issues/7434", "summary": "Replace a shuffle-store sizing heuristic that depends on a prior store's stats with a self-contained counting pre-pass, so bucket sizing doesn't depend on external state.", "howto": "Add a lightweight counting pass over the input shards before the shuffle-store write begins, use its output to size buckets directly, and delete the cross-store stat dependency once the pre-pass is validated to produce equivalent bucket sizes on a known case.", "id": "datakit-reliability-9"}, {"bucket": "datakit-reliability", "source": "github", "ref": 8234, "title": "Run the Harrier embedding pool on Marin's inference stack", "url": "https://github.com/marin-community/marin/issues/8234", "summary": "The Harrier embedding-pool service re-implements job submission/readiness/teardown logic that Marin's inference stack already provides; should reuse the existing implementation.", "howto": "Read how the existing inference stack does job submission/readiness/teardown, swap Harrier's bespoke versions for calls into that shared implementation, and delete the duplicated logic once a smoke test confirms embeddings still come back correctly.", "id": "datakit-reliability-10"}, {"bucket": "datakit-reliability", "source": "github", "ref": 8239, "title": "Verify ID properties after normalization", "url": "https://github.com/marin-community/marin/issues/8239", "summary": "Add a verification step after each normalize step so the pipeline stops rather than silently propagating shards that violate expected ID properties.", "howto": "Define the ID invariants that must hold post-normalize (uniqueness, stable format, non-null), add a cheap check step that runs right after normalize and hard-fails the ArtifactStep on violation, and backfill it onto the existing normalize steps one source at a time.", "id": "datakit-reliability-11"}, {"bucket": "datakit-reliability", "source": "github", "ref": 8248, "title": "Fix GHALogs output paths differing per region", "url": "https://github.com/marin-community/marin/issues/8248", "summary": "The GHALogs data-download chain hashes an absolute output path, so byte-identical data lands at a different content-addressed path in every region.", "howto": "Find where the absolute path enters the content hash, switch to a relative or canonicalized path before hashing, and verify by running the same download in two regions and diffing the resulting content-addressed keys.", "id": "datakit-reliability-12"}, {"bucket": "datakit-reliability", "source": "github", "ref": 8303, "title": "Register the hero quality data as proper Datakit steps", "url": "https://github.com/marin-community/marin/issues/8303", "summary": "Register the 'hero quality' dataset as proper Datakit steps so the store-ready dataset is a first-class pipeline output instead of an ad hoc artifact.", "howto": "Wrap the existing ad hoc build script as an ExecutorStep with declared inputs/outputs matching how other registered sources look, point the production mix config at the new step, and retire the ad hoc path once outputs match byte-for-byte.", "id": "datakit-reliability-13"}, {"bucket": "datakit-reliability", "source": "github", "ref": 8434, "title": "Fix highly compressed Parquet blobs OOMing rewrite workers", "url": "https://github.com/marin-community/marin/issues/8434", "summary": "Recompressing highly-compressed Parquet blobs can exceed the 8 GiB worker memory limit, causing the same shard to retry repeatedly across workers until the job gives up.", "howto": "Reproduce on the specific shard(s) that OOM, switch the rewrite to a streaming/row-group-at-a-time decode instead of loading the whole blob, and add a size-based pre-check that routes unusually dense blobs to a higher-memory worker pool rather than retrying blindly.", "id": "datakit-reliability-14"}, {"bucket": "datakit-reliability", "source": "github", "ref": 8497, "title": "Calibrate A/B benchmark parallelism to match the reference pipeline", "url": "https://github.com/marin-community/marin/issues/8497", "summary": "Calibrate the parallelism of a datakit A/B benchmark harness so it matches the resource shape (workers/CPU/RAM/disk) of the real reference pipeline.", "howto": "Pull the real pipeline's worker/CPU/RAM/disk config, mirror those exact numbers in the A/B harness's config, and re-run both sides to confirm the benchmark's absolute numbers now land close to production instead of just its relative ranking.", "id": "datakit-reliability-15"}, {"bucket": "datakit-reliability", "source": "github", "ref": 8580, "title": "Fix Tier-1 datakit smoke ferry exceeding its wait budget before tokenize", "url": "https://github.com/marin-community/marin/issues/8580", "summary": "The Tier-1 datakit smoke-test 'ferry' completed 6 of 7 stages but blew through its wait budget before the tokenize stage ran \u2014 a CI reliability gap in the datakit pipeline.", "howto": "Pull logs from a failing ferry run to see whether tokenize is queued-but-slow or never scheduled, then either raise the wait budget to match observed p99 latency or fix the scheduling gap directly \u2014 don't just widen the timeout without checking which it is.", "id": "datakit-reliability-16"}, {"bucket": "datakit-reliability", "source": "github", "ref": 8805, "title": "Fix fuzzy_dups CC shard failing on GCS 429 rate-limit", "url": "https://github.com/marin-community/marin/issues/8805", "summary": "The Nemotron-tier dedup pipeline fails when Google Cloud Storage rate-limits (429) a heavily-written output bucket during the connected-components stage.", "howto": "Add exponential backoff with jitter around the GCS write calls in the connected-components stage, and consider sharding output object-name prefixes to spread load across more GCS partitions, which is usually the actual fix for sustained 429s rather than just retrying harder.", "id": "datakit-reliability-17"}, {"bucket": "datakit-reliability", "source": "github", "ref": 8948, "title": "Fix verify_fuzzy_dups timing out waiting for a full 1000-worker pool", "url": "https://github.com/marin-community/marin/issues/8948", "summary": "The Nemotron-tier weekly dedup verification job times out waiting for its full 1000-worker pool to become ready, failing an otherwise-healthy pipeline run.", "howto": "Check whether the job truly needs all 1000 workers before starting or can begin with a partial pool and scale up, and raise the readiness timeout to match observed cluster ramp-up time in the meantime so a healthy-but-slow-to-provision run doesn't fail outright.", "id": "datakit-reliability-18"}]}, {"slug": "data-documentation-provenance", "stage": "cross-cutting", "name": "Data Documentation & Provenance", "blurb": "Making it possible for someone outside the immediate team to trace where training data actually came from.", "count": 1, "tasks": [{"bucket": "data-documentation-provenance", "source": "discord", "ref": "data-mixing \u00b7 2026-08-27", "title": "Publish a path for researchers to reconstruct/audit training-data provenance", "url": null, "summary": "In response to a request for detailed training-data metadata, the team noted they generally can't rehost underlying documents but should make provenance reconstruction possible for researchers with appropriate access.", "howto": "Document, per source, what's needed to reconstruct provenance without rehosting the documents themselves \u2014 typically a source ID plus a pointer back to the original public dataset/crawl and any transform steps applied \u2014 and publish it as a doc page rather than leaving it as tribal knowledge.", "id": "data-documentation-provenance-88"}]}], "count": 20}]};